#define main legacy_main
#include "blas-gemmEx-cuda/main.cu"
#undef main
#include <vector>
#include <functional>
#include <cmath>
#include <dlfcn.h>
#include <climits>
struct Case{std::function<bool()>run;std::function<std::vector<double>()>download;std::function<void()>prefetch;std::vector<double>want;int status;};
template<class T> T cast(float x){return T(x);}template<> __half cast<__half>(float x){return __float2half(x);}template<> __nv_bfloat16 cast<__nv_bfloat16>(float x){return __float2bfloat16(x);}
template<class T,class S,class CT> Case makecase(cublasHandle_t handle,int mode=0){const int m=32,n=32,k=16;T*A,*B;S*C;allocate_memory(m,n,k,&A,&B,&C);for(int i=0;i<m*k;i++)A[i]=cast<T>(std::is_same<T,int8_t>::value?float(i%17-8):float(i%17-8)/32);for(int i=0;i<k*n;i++)B[i]=cast<T>(std::is_same<T,int8_t>::value?float(i%13-6):float(i%13-6)/32);for(int i=0;i<m*n;i++)C[i]=cast<S>(0);CT alpha=cast<CT>(1),beta=cast<CT>(0);Case out;out.run=[=](){return cublas_gemm_ex(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,B,A,C,n,k,n,&alpha,&beta,-1,mode);};cudaDataType_t dt=std::is_same<T,double>::value?CUDA_R_64F:std::is_same<T,float>::value?CUDA_R_32F:std::is_same<T,__half>::value?CUDA_R_16F:std::is_same<T,__nv_bfloat16>::value?CUDA_R_16BF:CUDA_R_8I;cudaDataType_t ct=std::is_same<T,int8_t>::value?CUDA_R_32I:dt;cublasComputeType_t compute=std::is_same<T,double>::value?CUBLAS_COMPUTE_64F:std::is_same<T,int8_t>::value?CUBLAS_COMPUTE_32I:std::is_same<CT,__half>::value?CUBLAS_COMPUTE_16F:CUBLAS_COMPUTE_32F;out.status=int(cublasGemmEx(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,&alpha,B,dt,n,A,dt,k,&beta,C,ct,n,compute,CUBLAS_GEMM_DEFAULT));bool good=out.run();cudaDeviceSynchronize();if(good!=(out.status==0))abort();out.prefetch=[=](){cudaMemPrefetchAsync(A,m*k*sizeof(T),0);cudaMemPrefetchAsync(B,k*n*sizeof(T),0);cudaMemPrefetchAsync(C,m*n*sizeof(S),0);};out.download=[=](){cudaDeviceSynchronize();std::vector<S>host(m*n);cudaMemcpy(host.data(),C,m*n*sizeof(S),cudaMemcpyDeviceToHost);std::vector<double>result(m*n);for(int i=0;i<m*n;i++)result[i]=double(host[i]);return result;};for(int row=0;row<m;row++)for(int col=0;col<n;col++){int z=0;for(int j=0;j<k;j++)z+=((row*k+j)%17-8)*((j*n+col)%13-6);out.want.push_back(std::is_same<T,int8_t>::value?double(z):double(z)/1024);}return out;}
int main(){cublasHandle_t handle;if(cublasCreate(&handle)!=CUBLAS_STATUS_SUCCESS)return 2;Dl_info info;dladdr((void*)cublasCreate_v2,&info);char real[PATH_MAX];int version;cublasGetVersion(handle,&version);printf("STUDY_LIBRARY path=%s version=%d\n",realpath(info.dli_fname,real),version);std::vector<Case>cases;cases.push_back(makecase<double,double,double>(handle));for(int m:{3,2,1,0})cases.push_back(makecase<float,float,float>(handle,m));cases.push_back(makecase<__half,__half,__half>(handle));cases.push_back(makecase<__half,__half,float>(handle));cases.push_back(makecase<__nv_bfloat16,__nv_bfloat16,float>(handle));cases.push_back(makecase<int8_t,int32_t,int32_t>(handle));for(int i=0;i<9;i++){printf("STUDY_CASE index=%d status=%d\n",i,cases[i].status);if(cases[i].status!=0&&i!=7)return 3;}for(int trial=1;trial<=5;trial++){for(auto&c:cases)if(c.status==0)c.prefetch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;std::vector<double>out,want;for(auto&c:cases){out.push_back(c.status);want.push_back(c.status);}double total=0,err=0;bool ok=true;for(auto&c:cases)if(c.status==0){for(int j=0;j<10;j++){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();bool success=c.run();if(cudaDeviceSynchronize()!=cudaSuccess||!success)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;}auto values=c.download();out.insert(out.end(),values.begin(),values.end());want.insert(want.end(),c.want.begin(),c.want.end());}for(size_t i=0;i<out.size();i++){err=std::max(err,fabs(out[i]-want[i]));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-want[i])<=.004;}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.15g,\"timing_region\":\"sum_supported_gemmex_vendor_call_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",out.size(),err,path,out.size());if(!ok)return 1;}cublasDestroy(handle);}
